/* OSDuo Business Connect service worker (auto-generated by www/sw.py — do not edit on the server) */
const VERSION = "{{ cache_version }}";
const STATIC_CACHE = "bc-static-" + VERSION;
const PAGE_CACHE = "bc-pages-" + VERSION;
const MAX_STATIC_ENTRIES = 400;
const MAX_PAGE_ENTRIES = 25;

self.addEventListener("install", (event) => {
	event.waitUntil(
		caches
			.open(PAGE_CACHE)
			.then((cache) => cache.add("/offline"))
			.catch(() => {})
	);
	self.skipWaiting();
});

self.addEventListener("activate", (event) => {
	event.waitUntil(
		caches
			.keys()
			.then((keys) =>
				Promise.all(
					keys
						.filter((key) => key.startsWith("bc-") && !key.endsWith(VERSION))
						.map((key) => caches.delete(key))
				)
			)
			.then(() => self.clients.claim())
	);
});

self.addEventListener("message", (event) => {
	if (event.data && event.data.type === "BC_SKIP_WAITING") {
		self.skipWaiting();
	}
});

const isStaticAsset = (url) => url.pathname.startsWith("/assets/") || url.pathname.startsWith("/files/");

const isPublicPage = (url) =>
	url.pathname === "/login" ||
	url.pathname.startsWith("/b/") ||
	url.pathname.startsWith("/c/") ||
	url.pathname === "/offline";

// Never cached: API responses, private files, and authenticated desk routes.
const neverCached = (url) =>
	url.pathname.startsWith("/api/") ||
	url.pathname.startsWith("/private/") ||
	url.pathname.startsWith("/app") ||
	url.pathname.startsWith("/desk");

self.addEventListener("fetch", (event) => {
	const request = event.request;
	if (request.method !== "GET") return;

	const url = new URL(request.url);
	if (url.origin !== self.location.origin) return;
	if (neverCached(url)) return;

	if (isStaticAsset(url)) {
		event.respondWith(cacheFirst(request, STATIC_CACHE));
	} else if (isPublicPage(url)) {
		event.respondWith(networkFirst(request, PAGE_CACHE));
	}
});

async function cacheFirst(request, cacheName) {
	const cache = await caches.open(cacheName);
	const cached = await cache.match(request);
	if (cached) return cached;

	const response = await fetch(request);
	if (response && response.ok && response.type === "basic") {
		cache.put(request, response.clone());
		trimCache(cache, MAX_STATIC_ENTRIES);
	}
	return response;
}

async function networkFirst(request, cacheName) {
	const cache = await caches.open(cacheName);
	try {
		const response = await fetch(request);
		if (response && response.ok && response.type === "basic") {
			cache.put(request, response.clone());
			trimCache(cache, MAX_PAGE_ENTRIES);
		}
		return response;
	} catch (networkError) {
		const cached = await cache.match(request);
		if (cached) return cached;
		const offline = await cache.match("/offline");
		if (offline) return offline;
		throw networkError;
	}
}

async function trimCache(cache, maxEntries) {
	const keys = await cache.keys();
	if (keys.length <= maxEntries) return;
	// Oldest entries first in key order — evict from the front.
	const excess = keys.length - maxEntries;
	for (let i = 0; i < excess; i++) {
		await cache.delete(keys[i]);
	}
}
